// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount > 0);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(depositAmount <= type(uint256).max / 2);
        vm.assume(withdrawAmount <= depositAmount);

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok, "fallback fail");

        uint256 preUserBalance = c.balances(actor);
        uint256 preContractBalance = address(c).balance;
        uint256 expectedBalanceReduction = preUserBalance;

        vm.prank(actor);
        bool withdrewOk;
        try c.withdraw() { withdrewOk = true; } catch { withdrewOk = false; }

        assertTrue(withdrewOk ? (preContractBalance - address(c).balance == expectedBalanceReduction) : true);
    }
}
